const httpResponse = $input.first().json;
const productData = (httpResponse.body || {}).product || {};
const barcode = $('Validate - Normalize Input').item.json.barcode;
const nutriments = productData.nutriments || {};

const sugars = typeof nutriments.sugars_100g === 'number' ? nutriments.sugars_100g : null;
const salt = typeof nutriments.salt_100g === 'number' ? nutriments.salt_100g : null;
const fat = typeof nutriments.fat_100g === 'number' ? nutriments.fat_100g : null;
// El campo de energía trae un guion en el nombre ("energy-kcal_100g"), por eso se lee con notación de corchetes en vez de notación de punto.
const energyKcal = typeof nutriments['energy-kcal_100g'] === 'number' ? nutriments['energy-kcal_100g'] : null;

const sugarHigh = sugars !== null ? sugars > 22.5 : null;
const saltHigh = salt !== null ? salt > 1.5 : null;
const fatHigh = fat !== null ? fat > 17.5 : null;

const evaluated = [sugarHigh, saltHigh, fatHigh].filter(function (v) { return v !== null; });
const highs = [sugarHigh, saltHigh, fatHigh].filter(function (v) { return v === true; });

let semaforoLevel = null;
if (evaluated.length > 0) {
  if (highs.length === 0) semaforoLevel = 0;
  else if (highs.length === 1) semaforoLevel = 1;
  else semaforoLevel = 2;
}

const rawGrade = (productData.nutriscore_grade || '').toString().toLowerCase();
const nutriscoreValid = ['a', 'b', 'c', 'd', 'e'].indexOf(rawGrade) !== -1;
let nutriscoreLevel = null;
if (nutriscoreValid) {
  if (rawGrade === 'a' || rawGrade === 'b') nutriscoreLevel = 0;
  else if (rawGrade === 'c') nutriscoreLevel = 1;
  else nutriscoreLevel = 2;
}

const insufficientData = semaforoLevel === null && nutriscoreLevel === null;

let overallLevelNum = null;
if (!insufficientData) {
  const candidates = [semaforoLevel, nutriscoreLevel].filter(function (v) { return v !== null; });
  overallLevelNum = Math.max.apply(null, candidates);
}

const levelNames = ['saludable', 'moderado', 'no_saludable'];
const overallLevel = overallLevelNum !== null ? levelNames[overallLevelNum] : null;
const concernScore = evaluated.length > 0 ? highs.length : null;

return [{
  json: {
    barcode: barcode,
    product_name: productData.product_name || 'Producto sin nombre registrado',
    brands: productData.brands || null,
    sugars_100g: sugars,
    salt_100g: salt,
    fat_100g: fat,
    energy_kcal_100g: energyKcal,
    sugar_high: sugarHigh,
    salt_high: saltHigh,
    fat_high: fatHigh,
    nutriscore_grade: nutriscoreValid ? rawGrade : null,
    semaforo_level: semaforoLevel,
    nutriscore_level: nutriscoreLevel,
    overall_level: overallLevel,
    concern_score: concernScore,
    insufficient_data: insufficientData
  }
}];

